//! Required OL reversed boolean reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><ol id=list type=MiXeD reversed=legacy>Fallback ordered list</ol><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://ol-reversed.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn ol_reversed_canonical_boolean_accessor_and_actual_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),P=HTMLOListElement.prototype,a=Object.getOwnPropertyDescriptor(P,'reversed');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get reversed'||a.set.name!=='set reversed'||Object.hasOwn(x,'reversed')||x.reversed!==true||x.getAttribute('reversed')!=='legacy'||x.type!=='MiXeD'||document.createElement('ol').reversed!==false)throw 'canonical reversed boolean';"#);}
#[test]
fn ol_reversed_native_boolean_conversion_identity_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),old=x.getAttributeNode('reversed'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.reversed=false;var records=watch.takeRecords();if(x.reversed!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='reversed')throw 'false removes actual attribute';var calls=0;x.reversed={toString:function(){calls++;return '';},valueOf:function(){calls++;return 0;}};var attr=x.getAttributeNode('reversed');records=watch.takeRecords();if(calls||x.reversed!==true||attr===null||attr.value!==''||records.length!==1||records[0].oldValue!==null||x.type!=='MiXeD'||document.getElementById('neighbor').value!=='seed')throw 'boolean conversion keeps actual record';x.reversed='';if(x.reversed!==false||attr.ownerElement!==null)throw 'empty string is false';"#);}
#[test]
fn ol_reversed_inert_exact_namespace_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:ol');if(!(x instanceof HTMLOListElement)||x.reversed!==false)throw 'inert absent reversed';x.setAttributeNS('urn:foreign','reversed','foreign');x.setAttributeNS(null,'REVERSED','upper');if(x.reversed!==false)throw 'exact reversed namespace and case';x.reversed=true;var attr=x.getAttributeNodeNS(null,'reversed');if(x.reversed!==true||attr===null||attr.value!=='')throw 'inert actual boolean';x.removeAttributeNS('urn:foreign','reversed');x.removeAttributeNS(null,'REVERSED');var clone=x.cloneNode(false),copy=document.importNode(x,false);if(!(clone instanceof HTMLOListElement)||!(copy instanceof HTMLOListElement)||clone.reversed!==true||copy.reversed!==true||copy.ownerDocument!==document||clone.getAttributeNode('reversed')===attr)throw 'independent boolean copies';clone.reversed=false;if(x.reversed!==true||copy.reversed!==true||clone.reversed!==false)throw 'independent reversed removal';"#);}

#[test]
fn ol_reversed_truthiness_does_not_invoke_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),a=Object.getOwnPropertyDescriptor(HTMLOListElement.prototype,'reversed'),calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.reversed!==false||x.hasAttribute('reversed'))throw 'false boolean value';}for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('boolean'),BigInt(1),author]){a.set.call(x,value);if(x.reversed!==true||x.getAttribute('reversed')!==''||calls)throw 'true boolean value';}a.set.call(x);if(x.reversed!==false||calls||x.type!=='MiXeD')throw 'missing boolean argument';"#);}
#[test]
fn ol_reversed_brand_precedes_hooks_and_keeps_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),C=HTMLOListElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'reversed'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('ul'),document.createElement('li'),document.createElement('dl'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','ol'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OL')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'reversed getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return '';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'reversed setter brand';}Object.defineProperty(x,'reversed',{value:'author',writable:true,configurable:true});a.set.call(x,false);if(x.reversed!=='author'||x.hasAttribute('reversed'))throw 'canonical attribute authority';delete x.reversed;if(x.reversed!==false||Object.hasOwn(x,'reversed'))throw 'restored inherited boolean';delete window.HTMLOListElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved canonical interface';"#);}
#[test]
fn ol_reversed_raw_attribute_aliases_observe_presence_and_preserve_exact_backing(){let(mut d,mut f,mut p)=fixture();for inert in [false,true]{run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','ol');x.reversed=true;"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('reversed'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','nodeValue','textContent']){a[key]='R\ud800'+key;if(x.reversed!==true||a.value!=='R\ud800'+key||x.getAttributeNode('reversed')!==a)throw 'raw boolean backing';}var old=a.value;x.reversed=true;var records=watch.takeRecords();if(x.reversed!==true||a.value!==''||records.length!==4||records[3].oldValue!==old||x.getAttributeNode('reversed')!==a)throw 'boolean normalization uses current Attr';x.removeAttribute('reversed');if(x.reversed!==false||a.ownerElement!==null)throw 'actual boolean removal';x.setAttributeNS('urn:foreign','reversed','foreign');x.setAttributeNS(null,'REVERSED','upper');if(x.reversed!==false)throw 'exact reversed authority';x.setAttributeNS(null,'reversed','A\udfffZ');var clone=x.cloneNode(false);if(!x.reversed||!clone.reversed||clone.getAttributeNodeNS(null,'reversed').value!=='A\udfffZ'||clone.getAttributeNodeNS(null,'reversed')===x.getAttributeNodeNS(null,'reversed'))throw 'raw presence copy';"#);}}
#[test]
fn ol_reversed_saved_child_origin_refuses_before_observation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOListElement.prototype,'reversed');a.set.call(x,false);if(a.get.call(x)!==false)throw 'same origin boolean';");p.set_location(&crate::navigation::address("https://other-reversed.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,true);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://ol-reversed.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(x.reversed!==false)throw 'origin refusal preserves value';a.set.call(x,true);if(!a.get.call(x)||x.getAttribute('reversed')!=='')throw 'saved boolean recovery';");}

#[test]
fn ol_reversed_native_adoption_copy_and_template_keep_real_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),attr=x.getAttributeNode('reversed'),first=x.firstChild,copy=x.cloneNode(true),doc=new Document();if(!copy.reversed||copy.getAttribute('reversed')!=='legacy'||copy.firstChild===first)throw 'native boolean clone';doc.adoptNode(x);if(!x.reversed||x.getAttributeNode('reversed')!==attr||attr.ownerDocument!==doc||x.firstChild!==first)throw 'actual boolean adoption';document.adoptNode(x);document.body.appendChild(x);copy.reversed=false;if(!x.reversed||copy.reversed||attr.ownerElement!==x||x.type!=='MiXeD')throw 'independent copy removal';var template=document.createElement('template'),leaf=x.cloneNode(false);template.content.appendChild(leaf);document.body.appendChild(template);if(!leaf.reversed||leaf.ownerDocument!==template.content.ownerDocument||leaf.getAttribute('reversed')!=='legacy')throw 'actual boolean template parking';"#);}
#[test]
fn ol_reversed_writer_resource_refusal_is_atomic_and_recovers(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','ol');"}else{"var x=document.getElementById('list');x.reversed=false;"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("x.reversed=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.reversed!==false||watch.takeRecords().length)throw 'atomic reversed refusal';x.reversed=true;var records=watch.takeRecords();if(x.reversed!==true||x.getAttribute('reversed')!==''||records.length!==1||records[0].oldValue!==null)throw 'fresh boolean recovery';");}}}
#[test]
fn ol_reversed_reads_charge_names_work_and_deadline_without_string_copy_or_retained_growth(){for inert in [false,true]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let object=if inert{let Value::Host(object)=p.runtime.execute("var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','ol');x.reversed=true;x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert OL")};object}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("list")).unwrap())};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.ol_reversed_get(object);if mode==2{assert!(matches!(result,Ok(Value::Bool(true))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.ol_reversed_get(object),Ok(Value::Bool(true))));}}}
#[test]
fn ol_reversed_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["ol"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('list');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.reversed='exact';source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.reversed='exact';source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('reversed');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('reversed')!==oldValue||watch.takeRecords().length)throw 'atomic gauge lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('reversed')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.reversed!==source.reversed||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

#[test]
fn ol_reversed_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["ol"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.reversed='exact';source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('reversed');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('reversed')!==attr||source.reversed!==true||source.parentNode!==target)throw 'reserved native gauge connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}

#[test]
fn ol_reversed_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="ol"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','ol'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.reversed!==true)throw 'active content copy guard';");}
}

